// Answer the bands as records in constructor shape, so the table rebuilds from them: `fin.tiered_rates(t.bands()) ==
// t`.
//
//kavun:member bands pure () -> array
func tieredRatesBands(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	t := TieredRatesOf(v)
	bs := t.Bands()
	out := make([]core.Value, len(bs))
	for i, b := range bs {
		out[i] = rateBandValue(b)
	}
	return core.NewArrayValue(out, false), nil
}

// Answer the band `amount` falls in, as `{from, rate}`.
//
//kavun:member at pure (amount) -> record
func tieredRatesAt(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	name := id.String()
	t := TieredRatesOf(v)
	// at(amount) -> {from, rate}: the band the amount falls in, no arithmetic
	amount, err := core.DecimalOperandArg(name, "amount", args[0])
	if err != nil {
		return core.Undefined, err
	}
	b, err := t.At(amount)
	if err != nil {
		return core.Undefined, Error(name, err)
	}
	return rateBandValue(b), nil
}

// Answer the charge on `amount` under `rule`, rounded once.
//
// ```go
// fin := import("fin")
// tr := fin.tiered_rates("0:0.005, 1000:0.007, 10000:0.009")
// tr.charge(15000, "whole", 2, "half_even")       // => 135.00d — all of it at the 10000 band's rate
// tr.charge(15000, "marginal", 2, "half_even")    // => 113.00d — 5.00 + 63.00 + 45.00
// ```
//
//kavun:member charge pure (amount, rule, scale, mode) -> decimal
func tieredRatesCharge(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	name := id.String()
	t := TieredRatesOf(v)
	amount, rule, out, err := chargeArgs(name, args)
	if err != nil {
		return core.Undefined, err
	}
	d, err := t.Charge(amount, rule, out)
	return decimal(name, d, err)
}

